try {
  const getObj = (nodeName) => {
    try {
      const data = $(nodeName).item.json;
      if (typeof data === 'string') {
        return JSON.parse(data);
      }
      return data;
    } catch (e) {
      return null;
    }
  };

  const constants = getObj("Read Constants");
  const settings = getObj("Read Settings");
  const env = getObj("Read Environment");
  const schema = getObj("Read Schema");
  const hunterMap = getObj("Read Hunter Map");
  const validation = getObj("Read Validation");
  const rules = getObj("Read Search Rules");
  const params = getObj("Read Search Params");
  const outputMap = getObj("Read Output Map");
  const brightData = getObj("Read BrightData Map");

  const required = {
    file_constants: constants,
    file_settings: settings,
    file_env: env,
    file_schema: schema,
    file_hunter: hunterMap,
    file_val: validation,
    file_rules: rules,
    file_params: params,
    file_out: outputMap,
    file_bd: brightData
  };

  const missing = Object.keys(required).filter(k => required[k] === null || Object.keys(required[k]).length === 0);

  if (missing.length > 0) {
    return [{
      json: {
        status: "FAIL",
        missingFiles: missing,
        errorMessage: `CRITICAL: Missing or invalid configuration files: ${missing.join(', ')}`,
        constants: constants || {},
        settings: settings || {},
        env: env || {},
        schema: schema || {},
        hunterMap: hunterMap || {},
        validation: validation || {},
        rules: rules || {},
        params: params || {},
        outputMap: outputMap || {},
        brightData: brightData || {}
      }
    }];
  }

  return [{
    json: {
      status: "PASS",
      missingFiles: [],
      errorMessage: "",
      baseDir: $("Set Config Base Dir").item.json.baseDir,
      constants,
      settings,
      env,
      schema,
      hunterMap,
      validation,
      rules,
      params,
      outputMap,
      brightData
    }
  }];
} catch (e) {
  return [{
    json: {
      status: "FAIL",
      missingFiles: ["all"],
      errorMessage: `CRITICAL: Uncaught exception in consolidator: ${e.message}`,
      constants: {},
      settings: {},
      env: {},
      schema: {},
      hunterMap: {},
      validation: {},
      rules: {},
      params: {},
      outputMap: {},
      brightData: {}
    }
  }];
}

try {
  const items = $input.all();
  if (items.length === 0 || !items[0].json.data) {
    return [];
  }

  const csvText = items[0].json.data;

  // 1. Read checkpoint from Google Sheets
  let completedSearchIDs = new Set();
  try {
    const checkpointRows = $('Read Checkpoint').all();
    for (const row of checkpointRows) {
      if (row.json && row.json.SearchID && row.json.Status === 'completed') {
        completedSearchIDs.add(row.json.SearchID);
      }
    }
    console.log(`Loaded ${completedSearchIDs.size} completed searches from checkpoint.`);
  } catch (e) {
    console.log("No existing checkpoint found or failed to read checkpoint:", e.message);
  }

  // Parse CSV manually
  const lines = [];
  let row = [""];
  let inQuotes = false;

  for (let i = 0; i < csvText.length; i++) {
    const c = csvText[i];
    const next = csvText[i+1];

    if (c === '"') {
      if (inQuotes && next === '"') {
        row[row.length - 1] += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (c === ',') {
      if (inQuotes) {
        row[row.length - 1] += c;
      } else {
        row.push("");
      }
    } else if (c === '\r' || c === '\n') {
      if (inQuotes) {
        row[row.length - 1] += c;
      } else {
        if (c === '\r' && next === '\n') {
          i++;
        }
        lines.push(row);
        row = [""];
      }
    } else {
      row[row.length - 1] += c;
    }
  }
  if (row.length > 1 || row[0] !== "") {
    lines.push(row);
  }

  if (lines.length < 2) {
    return [];
  }

  const headers = lines[0].map(h => (h || '').toString().trim());
  const allQueries = [];

  for (let i = 1; i < lines.length; i++) {
    const values = lines[i];
    if (values.length < headers.length) continue;
    const obj = {};
    for (let j = 0; j < headers.length; j++) {
      const val = values[j] ? (values[j] || '').toString().trim() : "";
      if (headers[j] === 'CityID' || headers[j] === 'CategoryID' || headers[j] === 'PriorityTier') {
        obj[headers[j]] = parseInt(val, 10) || 0;
      } else {
        obj[headers[j]] = val;
      }
    }
    allQueries.push(obj);
  }

  // 2. Filter out completed searches
  const pendingQueries = allQueries.filter(q => !completedSearchIDs.has(q.SearchID));
  const completedBefore = completedSearchIDs.size;
  const totalQueries = allQueries.length;

  // 3. Get chunk size from config
  const params = $('Parse, Consolidate & Validate').item.json.params;
  const chunkSize = params?.batchControl?.chunkSize || 100;

  const chunkQueries = pendingQueries.slice(0, chunkSize);
  console.log(`Total queries: ${totalQueries} | Completed before: ${completedBefore} | Pending: ${pendingQueries.length} | Chunk size: ${chunkSize} | Processing in this run: ${chunkQueries.length}`);

  // Inject state metadata
  return chunkQueries.map(q => {
    return {
      json: {
        ...q,
        completedBefore: completedBefore,
        totalQueries: totalQueries,
        chunkSize: chunkSize
      }
    };
  });
} catch (e) {
  console.error("Error in Parse Search Data:", e.message);
  return [];
}

try {
  let staticData;
  try {
    staticData = $getWorkflowStaticData('global') || {};
  } catch (e) {
    staticData = {};
  }

  // Safely validate static data before use
  if (!staticData || typeof staticData !== 'object') {
    staticData = {};
  }
  staticData.completed = Array.isArray(staticData.completed) ? staticData.completed : [];
  staticData.failed = Array.isArray(staticData.failed) ? staticData.failed : [];
  staticData.retryQueue = Array.isArray(staticData.retryQueue) ? staticData.retryQueue : [];
  staticData.creditsUsed = typeof staticData.creditsUsed === 'number' ? staticData.creditsUsed : 0;
  staticData.businessesExported = typeof staticData.businessesExported === 'number' ? staticData.businessesExported : 0;
  staticData.emailsFound = typeof staticData.emailsFound === 'number' ? staticData.emailsFound : 0;
  staticData.phonesFound = typeof staticData.phonesFound === 'number' ? staticData.phonesFound : 0;
  staticData.startTime = staticData.startTime || new Date().toISOString();

  const items = $input.all();
  const validQueries = items.filter(i => {
    const q = i.json.SearchQuery;
    return q && (q || '').toString().trim() !== '';
  });

  staticData.completedBefore = items[0]?.json.completedBefore || 0;
  staticData.totalQueries = items[0]?.json.totalQueries || 3874;

  // Deduplicate retry queue and active pending
  const pending = validQueries.filter(item => {
    const sId = item.json.SearchID;
    return !staticData.completed.includes(sId) && !staticData.failed.includes(sId);
  });

  staticData.pendingSearches = pending.length;

  // Dynamic Batch Sizing Logic
  const baseBatch = 10;
  const successRate = staticData.totalQueries > 0 ? ((staticData.completedBefore + staticData.completed.length) / staticData.totalQueries) : 1;
  let dynamicBatchSize = baseBatch;

  if (successRate > 0.9 && (staticData.completedBefore + staticData.completed.length) > 50) dynamicBatchSize = 20;
  if (successRate > 0.95 && (staticData.completedBefore + staticData.completed.length) > 200) dynamicBatchSize = 50;
  if (successRate < 0.7) dynamicBatchSize = 5;

  staticData.currentBatchSize = dynamicBatchSize;

  console.log(`[DASHBOARD] Total: ${staticData.totalQueries} | Completed before: ${staticData.completedBefore} | Pending in chunk: ${pending.length} | Chunk size: ${items.length} | Batch Size: ${dynamicBatchSize}`);

  return pending;
} catch (e) {
  console.error("Error in Dashboard & Batch Init:", e.message);
  return [];
}

const items = $input.all();
const ctx = $('Save Snapshot Context').first().json;
const configs = $items('Parse, Consolidate & Validate')[0].json;
const rules = configs.rules || {};
const validation = configs.validation || {};

const blockedDomains = rules.resultFiltering?.skipIfWebsiteContains || ['justdial','indiamart','tradeindia','facebook','instagram','linkedin','twitter','youtube','sulekha'];
const indianMobileRegex = validation.phoneValidation?.regexPatterns?.indianMobile ? new RegExp(validation.phoneValidation.regexPatterns.indianMobile) : /^[6-9]\d{9}$/;
const pincodeRegex = validation.phoneValidation?.regexPatterns?.pincode ? new RegExp(validation.phoneValidation.regexPatterns.pincode) : /\b[1-9][0-9]{5}\b/;

function isBlockedWebsite(url) {
  if (!url) return false;
  const u = url.toLowerCase();
  return blockedDomains.some(b => u.includes(b));
}
function prefixHttps(url) {
  if (!url) return '';
  return url.startsWith('http') ? url : 'https://' + url;
}

const output = [];
for (const item of items) {
  const d = item.json;
  const name = (d.name || '').trim();
  if (!name || name.length < 3) continue;

  const website = isBlockedWebsite(d.open_website || d.website) ? '' : prefixHttps(d.open_website || d.website || '');

  let rawPhone = String(d.phone_number || d.phone || '').replace(/[\s\-().+]/g, '');
  if (rawPhone.startsWith('91') && rawPhone.length === 12) rawPhone = rawPhone.slice(2);
  if (rawPhone.startsWith('0') && rawPhone.length === 11) rawPhone = rawPhone.slice(1);
  const phone = indianMobileRegex.test(rawPhone) ? rawPhone : '';

  const address = (d.address || '').trim();
  const pincodeMatch = address.match(pincodeRegex);
  const pincode = pincodeMatch ? pincodeMatch[0] : '';

  output.push({
    json: {
      searchId: ctx.SearchID,
      category: ctx.Category,
      cityName: ctx.Location,
      businessName: name,
      pincode: pincode,
      primaryPhone: phone,
      website: website,
      address: address,
      rating: d.rating || '',
      reviewsCount: d.reviews_count || '',
      googleMapsUrl: d.url || '',
      primaryEmail: ''
    }
  });
}
return output;

try {
  const items = $input.all();
  // Robust Regex for Deep Extraction
  const emailRegex = /[a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9_-]+/gi;
  const telRegex = /href=["']tel:([^"]+)["']/gi;
  const mailtoRegex = /href=["']mailto:([^"]+)["']/gi;
  const phoneRegex = /(?:\+?91|0)?[ -]?(?:[6-9][0-9]{9})/g;
  const gstRegex = /\d{2}[A-Z]{5}\d{4}[A-Z]{1}[A-Z\d]{1}[Z]{1}[A-Z\d]{1}/gi;

  return items.map(item => {
    let html = '';
    try {
      if (item && item.json && item.json.data) {
        if (typeof item.json.data === 'string') {
          html = item.json.data;
        } else if (typeof item.json.data === 'object') {
          html = JSON.stringify(item.json.data);
        }
      }
    } catch (e) {
      html = '';
    }

    let emails = new Set();
    let phones = new Set();
    let gstins = new Set();

    if (html && typeof html === 'string') {
      try {
        // Extract Mailto
        const mMailto = [...html.matchAll(mailtoRegex)];
        mMailto.forEach(m => {
          if (m && m[1]) {
            emails.add((m[1].split('?')[0] || '').toString().trim().toLowerCase());
          }
        });
      } catch (e) {}

      try {
        // Extract Body Emails (Filter out images)
        const mEmails = html.match(emailRegex) || [];
        mEmails.forEach(e => {
          if (e) {
            const el = e.toLowerCase();
            if(!el.endsWith('.png') && !el.endsWith('.jpg') && !el.endsWith('.gif') && !el.endsWith('.jpeg') && !el.endsWith('.webp') && !el.includes('sentry') && !el.includes('wix')) {
              emails.add(el);
            }
          }
        });
      } catch (e) {}

      try {
        // Extract Tel Links
        const mTel = [...html.matchAll(telRegex)];
        mTel.forEach(m => {
          if (m && m[1]) {
            const cleaned = m[1].replace(/[^\d]/g, '');
            if (cleaned.length >= 10) phones.add(cleaned.slice(-10));
          }
        });
      } catch (e) {}

      try {
        // Extract Body Phones
        const mPhones = html.match(phoneRegex) || [];
        mPhones.forEach(p => {
          if (p) {
            const cleaned = p.replace(/[^\d]/g, '');
            if (cleaned.length === 10 || (cleaned.length === 12 && cleaned.startsWith('91'))) {
              phones.add(cleaned.length === 12 ? cleaned.substring(2) : cleaned);
            }
          }
        });
      } catch (e) {}

      try {
        // Extract GST
        const mGst = html.match(gstRegex) || [];
        mGst.forEach(g => {
          if (g) gstins.add(g.toUpperCase());
        });
      } catch (e) {}
    }

    const out = item && item.json ? { ...item.json } : {};
    delete out.data; // Memory optimization: drop HTML payload

    const emailArr = Array.from(emails);
    const phoneArr = Array.from(phones);

    // Prioritize professional emails over generic if multiple exist
    let bestEmail = emailArr[0];
    for (let e of emailArr) {
      if (e && (e.includes('sales@') || e.includes('purchase@') || e.includes('director@'))) bestEmail = e;
    }

    if (!out.primaryEmail && bestEmail) out.primaryEmail = bestEmail;
    if (!out.primaryPhone && phoneArr.length > 0) out.primaryPhone = phoneArr[0];
    if (gstins.size > 0) out.gstNumber = Array.from(gstins)[0];

    return { json: out };
  });
} catch (e) {
  console.error("Error in Extract Deep Contact Info:", e.message);
  return $input.all().map(item => {
    const out = item && item.json ? { ...item.json } : {};
    delete out.data;
    return { json: out };
  });
}

const items = $input.all();
return items.map(item => {
  const d = item.json;
  let score = 0;
  let breakdown = {};

  if (d.businessName) { score += 15; breakdown.name = 15; }
  if (d.primaryPhone) { score += 20; breakdown.phone = 20; }
  if (d.website) {
    score += 15;
    breakdown.website = 15;
    if (d.website.startsWith('https')) { score += 5; breakdown.https = 5; }
  }
  if (d.address) { score += 10; breakdown.address = 10; }
  if (d.pincode) { score += 5; breakdown.pincode = 5; }
  if (d.rating && parseFloat(d.rating) >= 4.0) { score += 5; breakdown.rating = 5; }
  if (d.reviewsCount && parseInt(d.reviewsCount) >= 10) { score += 5; breakdown.reviews = 5; }
  if (d.primaryEmail) { score += 15; breakdown.email = 15; }
  if (d.gstNumber) { score += 5; breakdown.gst = 5; }

  d.leadScore = Math.min(score, 100);
  d.scoreBreakdown = breakdown;

  return { json: d };
});

try {
  const items = $input.all();
  const originalLeads = $('Enrich with Hunter?').all(0, 0);

  return items.map((item, i) => {
    const lead = originalLeads[i] ? { ...originalLeads[i].json } : (item && item.json ? { ...item.json } : {});
    const d = item && item.json ? item.json : {};

    if (lead && !lead.primaryEmail && d.data && d.data.emails && d.data.emails.length > 0) {
      const sortedEmails = d.data.emails.sort((a, b) => (b.confidence || 0) - (a.confidence || 0));
      const best = sortedEmails.find(e => e && e.verification && ['valid', 'accept_all'].includes(e.verification.status)) || sortedEmails[0];

      if (best && best.value) {
        lead.primaryEmail = (best.value || '').toString().toLowerCase();
        lead.hunterConfidence = best.confidence;
        lead.leadScore = Math.min((lead.leadScore || 0) + 10, 100);
      }
    }
    return { json: lead };
  });
} catch (e) {
  console.error("Error in Map Highest Confidence Hunter:", e.message);
  return $input.all();
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenBusinesses) staticData.seenBusinesses = {};

const items = $input.all();
const unique = [];

for (const item of items) {
  const d = item.json;
  const mapsUrl = (d.googleMapsUrl || '').trim().toLowerCase();
  const website = (d.website || '').trim().toLowerCase();
  const phone = (d.primaryPhone || '').trim();
  const name = (d.businessName || '').trim().toLowerCase();
  const address = (d.address || '').trim().toLowerCase();

  // Robust enterprise deduplication hierarchy
  const key = mapsUrl || website || phone || (name + '|' + address);
  if (!key || key === '|') continue;

  if (staticData.seenBusinesses[key]) {
    if ((d.leadScore || 0) > (staticData.seenBusinesses[key].leadScore || 0)) {
      staticData.seenBusinesses[key] = { leadScore: d.leadScore };
      const idx = unique.findIndex(u => u.json._dedupKey === key);
      if (idx !== -1) unique.splice(idx, 1, { json: { ...d, _dedupKey: key } });
      else unique.push({ json: { ...d, _dedupKey: key } });
    }
  } else {
    staticData.seenBusinesses[key] = { leadScore: d.leadScore || 0 };
    unique.push({ json: { ...d, _dedupKey: key } });

    // Dashboard Analytics Updator
    if(d.primaryEmail) staticData.emailsFound++;
    if(d.primaryPhone) staticData.phonesFound++;
    staticData.businessesExported++;
  }
}

return unique.map(u => {
  const j = { ...u.json };
  delete j._dedupKey;
  delete j.scoreBreakdown; // Strip heavy objects before export
  return { json: j };
});

const items = $input.all();
const configs = $items('Parse, Consolidate & Validate')[0].json;
const outMapping = configs.outputMap || {};
const columnsConfig = outMapping.columns || [];
if (columnsConfig.length > 0) columnsConfig.sort((a,b) => a.order - b.order);

return items.map(item => {
  const d = item.json;
  const out = {};
  if (columnsConfig.length > 0) {
    columnsConfig.forEach(c => {
      out[c.header] = d[c.internalField] || d[c.header] || "";
    });
  } else {
    out["Company Name"] = d.businessName || "";
    out["Pincode"] = d.pincode || "";
    out["Category"] = d.category || "";
    out["Location"] = d.cityName || "";
    out["Mobile NO"] = d.primaryPhone || "";
    out["Email"] = d.primaryEmail || "";
    out["Website"] = d.website || "";
    out["Address"] = d.address || "";
    // Added GST based on new extraction
    if(d.gstNumber) out["GST Number"] = d.gstNumber;
  }
  return { json: out };
});

try {
  let staticData;
  try {
    staticData = $getWorkflowStaticData('global') || {};
  } catch (e) {
    staticData = {};
  }

  if (!staticData || typeof staticData !== 'object') {
    staticData = {};
  }
  staticData.completed = Array.isArray(staticData.completed) ? staticData.completed : [];
  staticData.creditsUsed = typeof staticData.creditsUsed === 'number' ? staticData.creditsUsed : 0;

  const searchId = $('Save Snapshot Context').first().json.SearchID;

  if (searchId && !staticData.completed.includes(searchId)) {
    staticData.completed.push(searchId);
  }

  // Add to Estimated Credits Used (approx 0.005 per query)
  staticData.creditsUsed += 0.005;

  const total = staticData.totalQueries || 3874;
  const completed = (staticData.completedBefore || 0) + staticData.completed.length;
  const failed = staticData.failed?.length || 0;
  const remaining = total - (completed + failed);
  const successRate = total > 0 ? ((completed / total) * 100).toFixed(2) : 0;
  const runTimeMs = new Date() - new Date(staticData.startTime || new Date());
  const runTimeMin = (runTimeMs / 60000).toFixed(2);

  console.log(`[CHECKPOINT] SearchID: ${searchId} | Prog: ${completed}/${total} | Remaining: ${remaining} | Fail: ${failed} | SR: ${successRate}% | Time: ${runTimeMin}m | Exp: ${staticData.businessesExported} | Cost: $${staticData.creditsUsed.toFixed(3)}`);

  if(staticData.creditsUsed > 48.0) {
    console.warn("WARNING: Nearing daily budget limits. Please monitor execution.");
  }

  return [{
    json: {
      SearchID: searchId,
      Status: "completed",
      Timestamp: new Date().toISOString()
    }
  }];
} catch (e) {
  console.error("Error in Dashboard Update & Checkpoint:", e.message);
  return [{
    json: {
      Status: "error",
      Timestamp: new Date().toISOString(),
      error: e.message
    }
  }];
}

try {
  let staticData;
  try {
    staticData = $getWorkflowStaticData('global') || {};
  } catch (e) {
    staticData = {};
  }

  if (!staticData || typeof staticData !== 'object') {
    staticData = {};
  }
  staticData.failed = Array.isArray(staticData.failed) ? staticData.failed : [];
  staticData.retryQueue = Array.isArray(staticData.retryQueue) ? staticData.retryQueue : [];
  staticData.retryCount = typeof staticData.retryCount === 'number' ? staticData.retryCount : 0;

  const searchId = $input.first().json.SearchID || $('Process in Batches').item.json.SearchID || 'unknown';

  if (searchId !== 'unknown' && !staticData.failed.includes(searchId)) {
    staticData.failed.push(searchId);
    staticData.retryQueue.push(searchId);
    staticData.retryCount += 1;
  }
  console.error(`[FAILED] Registered failure for SearchID: ${searchId}. Added to retry queue.`);

  return [{
    json: {
      SearchID: searchId,
      Status: "failed",
      Timestamp: new Date().toISOString()
    }
  }];
} catch (e) {
  console.error("Error in Register Failed Search:", e.message);
  return [{
    json: {
      Status: "error",
      Timestamp: new Date().toISOString(),
      error: e.message
    }
  }];
}

try {
  let staticData;
  try {
    staticData = $getWorkflowStaticData('global') || {};
  } catch (e) {
    staticData = {};
  }

  const runTimeMs = new Date() - new Date(staticData.startTime || new Date());
  const runTimeMin = (runTimeMs / 60000).toFixed(2);

  const totalCompleted = (staticData.completedBefore || 0) + (staticData.completed?.length || 0);
  const totalQueries = staticData.totalQueries || 3874;
  const isFinalConsolidation = totalCompleted >= totalQueries;

  const successRate = totalQueries > 0 ? ((totalCompleted / totalQueries) * 100).toFixed(2) : 0;

  const report = {
    Execution_Summary: isFinalConsolidation ? "ALL_CHUNKS_COMPLETE" : "CHUNK_COMPLETE",
    Total_Searches: totalQueries,
    Completed_Before: staticData.completedBefore || 0,
    Completed_This_Run: staticData.completed?.length || 0,
    Total_Completed: totalCompleted,
    Failed_Permanent: staticData.failed?.length || 0,
    Businesses_Exported: staticData.businessesExported || 0,
    Emails_Found: staticData.emailsFound || 0,
    Phone_Numbers_Found: staticData.phonesFound || 0,
    Credits_Used_USD: staticData.creditsUsed ? parseFloat(staticData.creditsUsed.toFixed(3)) : 0,
    Execution_Time_Minutes: parseFloat(runTimeMin),
    Retry_Queue_Size: staticData.retryQueue?.length || 0,
    Is_Final_Consolidation: isFinalConsolidation,

    // Added production-grade metrics
    Skipped_Searches: staticData.completedBefore || 0,
    Duplicate_Records_Removed: staticData.duplicatesRemoved || 0,
    Execution_Success_Percent: parseFloat(successRate),
    Average_Businesses_Per_Search: totalCompleted > 0 ? parseFloat((staticData.businessesExported / totalCompleted).toFixed(2)) : 0,
    Average_Emails_Per_Search: totalCompleted > 0 ? parseFloat((staticData.emailsFound / totalCompleted).toFixed(2)) : 0,
    Average_Phones_Per_Search: totalCompleted > 0 ? parseFloat((staticData.phonesFound / totalCompleted).toFixed(2)) : 0,
    Total_Runtime: `${runTimeMin} minutes`,
    Retry_Count: staticData.retryCount || 0,
    Checkpoint_Count: staticData.completed?.length || 0
  };

  console.log("EXECUTION REPORT GENERATED:\n", JSON.stringify(report, null, 2));
  return [{ json: report }];
} catch (e) {
  console.error("Error in Final Execution Report:", e.message);
  return [{ json: { error: e.message } }];
}

try {
  const items = $input.all();
  console.log(`Loaded ${items.length} raw leads from Google Sheets for consolidation.`);

  const seen = new Set();
  const consolidated = [];

  for (const item of items) {
    if (item && item.json) {
      const name = (item.json["Company Name"] || "").toString().trim().toLowerCase();
      const phone = (item.json["Mobile NO"] || "").toString().trim();
      const key = `${name}|${phone}`;

      if (key && !seen.has(key)) {
        seen.add(key);
        consolidated.push(item.json);
      }
    }
  }

  // Update duplicates removed metric in static data safely
  try {
    let staticData = $getWorkflowStaticData('global');
    if (staticData && typeof staticData === 'object') {
      staticData.duplicatesRemoved = items.length - consolidated.length;
    }
  } catch (se) {}

  console.log(`Deduplication complete. Remaining leads: ${consolidated.length} (Removed ${items.length - consolidated.length} duplicates).`);

  return consolidated.map(lead => ({ json: lead }));
} catch (e) {
  console.error("Error in Consolidate & Deduplicate:", e.message);
  return $input.all();
}

