try {
  const items = $input.all();
  const passedChecks = [];
  const validationErrors = [];
  const report = {};

  // Helper to check and record
  const check = (name, condition, successMsg, failMsg) => {
    if (condition) {
      report[name] = "PASS";
      passedChecks.push(`✓ ${successMsg}`);
    } else {
      report[name] = "FAIL";
      validationErrors.push(`✗ ${failMsg}`);
    }
  };

  const config = (items && items[0] && items[0].json) ? items[0].json : {};

  // 1. Verify Files Loaded
  check("Constants Config", !!(config.constants && Object.keys(config.constants).length > 0), "Constants Config Loaded", "Constants Config (workflow_constants.json) Missing");
  check("Settings Config", !!(config.settings && Object.keys(config.settings).length > 0), "Settings Config Loaded", "Settings Config (workflow_settings.json) Missing");
  check("Environment Config", !!(config.env && Object.keys(config.env).length > 0), "Environment Config Loaded", "Environment Config (environment.json) Missing");
  check("Schema Config", !!(config.schema && Object.keys(config.schema).length > 0), "Schema Config Loaded", "Schema Config (output_schema.json) Missing");
  check("Hunter Map Config", !!(config.hunterMap && Object.keys(config.hunterMap).length > 0), "Hunter Map Config Loaded", "Hunter Map Config (hunter_mapping.json) Missing");
  check("Validation Rules Config", !!(config.validation && Object.keys(config.validation).length > 0), "Validation Rules Config Loaded", "Validation Rules Config (validation_rules.json) Missing");
  check("Search Rules Config", !!(config.rules && Object.keys(config.rules).length > 0), "Search Rules Config Loaded", "Search Rules Config (search_rules.json) Missing");
  check("Search Params Config", !!(config.params && Object.keys(config.params).length > 0), "Search Params Config Loaded", "Search Params Config (search_parameters.json) Missing");
  check("Output Map Config", !!(config.outputMap && Object.keys(config.outputMap).length > 0), "Output Map Config Loaded", "Output Map Config (output_mapping.json) Missing");
  check("Bright Data Map Config", !!(config.brightData && Object.keys(config.brightData).length > 0), "Bright Data Map Config Loaded", "Bright Data Map Config (brightdata_dataset_mapping.json) Missing");

  // 2. Verify Credentials Bound
  const envValues = config.env?.values || {};
  const googleSheetId = (envValues.GOOGLE_SHEET_ID || '').toString().trim();
  const driveFolderId = (envValues.GOOGLE_DRIVE_FOLDER_ID || '').toString().trim();
  const bdUsername = (envValues.BRIGHTDATA_USERNAME || '').toString().trim();
  const bdPassword = (envValues.BRIGHTDATA_PASSWORD || '').toString().trim();
  const hunterApiKey = (envValues.HUNTER_API_KEY || '').toString().trim();
  const sheetTabName = (envValues.GOOGLE_SHEET_TAB_NAME || '').toString().trim();

  const has_google = googleSheetId !== '';
  const has_drive = driveFolderId !== '';
  const has_bd = bdUsername !== '' && bdPassword !== '';

  check("Bright Data Credential", has_bd, "Bright Data Credential Configured", "Bright Data Credential Missing or Incomplete");
  check("Google Sheets Credential", has_google, "Google Sheets Credential Configured", "Google Sheets Credential Missing or Incomplete");
  check("Google Drive Credential", has_drive, "Google Drive Credential Configured", "Google Drive Credential Missing or Incomplete");

  // 3. Verify Env values
  check("Google Sheet ID", has_google, "Google Sheet ID Found", "Google Sheet ID Missing");
  check("Google Sheet Tab Name", sheetTabName !== '', "Google Sheet Tab Name Found", "Google Sheet Tab Name Missing");
  check("Google Drive Folder ID", has_drive, "Google Drive Folder ID Found", "Google Drive Folder ID Missing");
  check("Hunter API Key", hunterApiKey !== '', "Hunter API Key Found", "Hunter API Key Missing");
  check("Bright Data Username", bdUsername !== '', "Bright Data Username Found", "Bright Data Username Missing");
  check("Bright Data Password", bdPassword !== '', "Bright Data Password Found", "Bright Data Password Missing");

  // 4. Verify Bright Data API Endpoints
  const bd = config.brightData || {};
  const mapsDataset = bd.datasets?.googleMaps || {};
  const datasetId = (mapsDataset.datasetId || '').toString().trim();
  const triggerEndpoint = (mapsDataset.triggerEndpoint || '').toString().trim();
  const progressEndpoint = (mapsDataset.progressEndpoint || '').toString().trim();
  const snapshotEndpoint = (mapsDataset.snapshotEndpoint || '').toString().trim();

  check("Bright Data Dataset ID", datasetId !== '', "Bright Data Dataset ID Loaded", "Bright Data Dataset ID Missing");
  check("Bright Data Trigger Endpoint", triggerEndpoint !== '', "Bright Data Trigger Endpoint Loaded", "Bright Data Trigger Endpoint Missing");
  check("Bright Data Progress Endpoint", progressEndpoint !== '', "Bright Data Progress Endpoint Loaded", "Bright Data Progress Endpoint Missing");
  check("Bright Data Snapshot Endpoint", snapshotEndpoint !== '', "Bright Data Snapshot Endpoint Loaded", "Bright Data Snapshot Endpoint Missing");

  // 5. Verify Hunter Endpoints
  const hunter = config.hunterMap || {};
  const hunterUrl = (hunter.endpoints?.domainSearch?.url || '').toString().trim();
  check("Hunter Domain Search Endpoint", hunterUrl !== '', "Hunter Domain Search Endpoint Loaded", "Hunter Domain Search Endpoint Missing");

  const totalErrors = validationErrors.length;
  const readyForExecution = totalErrors === 0;
  const status = readyForExecution ? "PASS" : "FAIL";

  return [{
    json: {
      status,
      readyForExecution,
      totalErrors,
      passedChecks,
      validationErrors,
      configurationReport: report
    }
  }];
} catch (e) {
  return [{
    json: {
      status: "FAIL",
      readyForExecution: false,
      totalErrors: 1,
      passedChecks: [],
      validationErrors: [`✗ Internal Validator Crash: ${e.message}`],
      configurationReport: {}
    }
  }];
}

